fluid.def("fluid.demos.ai.noteImageGenerator", {
    $layers: ["fluid.demos.imageGenerator", "fluid.topLevelWidget"],
    // Hidden supplier: keeps finding the closest sticky note from this widget's position,
    // but renders nothing because it shares the view of this widget
    noteFinder: {
        $component: {
            $layers: "fluid.demos.closestNoteFinder",
            view: "{noteImageGenerator}.view"
        }
    },
    // The closest note's text becomes the image prompt
    state: {
        prompt: "{noteFinder}.noteText"
    }
});

